import type { getHouseholdImportHistory } from "@/features/import/api";

// SPEC FIXTURE: written from `GET /imports/history` (one flat row per import; rows of one upload group are one statement), not generated by the backend.
// Orchestrator-owned: never edit. Member ids are the ones in `members.ts`.
export type ImportHistoryRow = Awaited<ReturnType<typeof getHouseholdImportHistory>>[number];

function row(importId: string, memberId: string, groupId: string | null): ImportHistoryRow {
  return {
    import_id: importId,
    household_member_id: memberId,
    uploaded_at: "2026-09-10T10:30:00Z",
    statement_from_date: null,
    statement_to_date: null,
    status: "import_successful",
    new_transactions_count: 1,
    upload_group_id: groupId,
    member_name: "x",
    group_people_count: 1,
  };
}

// Aditi is in two statements (groups g1 and g2). The account holder is in group g1 twice (two rows, one statement) and in one
// statement with no group (counted by its own import id). Ramesh has none.
export const HISTORY_FIXTURE: ImportHistoryRow[] = [
  row("i1", "m-spouse", "g1"),
  row("i2", "m-spouse", "g2"),
  row("i3", "m-self", "g1"),
  row("i4", "m-self", null),
  row("i5", "m-self", "g1"),
];

// Worked by hand from the rows above.
export const HISTORY_STATEMENT_COUNTS: Record<string, number> = { "m-self": 2, "m-spouse": 2, "m-father": 0 };
